--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,87 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Already-imported tickets are skipped. The whole file is checked first; one
+// bad row or stock shortage and nothing is imported.
+import { AppError } from "../errors.js";
+import { isInstant } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports till sales from CSV; returns { tickets, dishes } or throws naming the row. */
+export function importSales(store, text) {
+  const [head, ...rawRows] = parseCsv(text);
+  if (!head) return { tickets: 0, dishes: 0 };
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+  const rows = rawRows.map((r) => Object.fromEntries(keys.map((k, i) => [k, (r[i] ?? "").trim()])));
+
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = Number(r.dishId);
+    if (!r.dishId || !Number.isInteger(dishId) || dishId < 1)
+      throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    const dish = (store.data.dishes ?? []).find((d) => d.id === dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish ${dishId}` });
+    const recipe = getRecipe(store, dish.recipeId);
+    const qty = Number(r.qty);
+    if (!r.qty || !Number.isInteger(qty) || qty < 1)
+      throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return {
+      where,
+      ticket: r.ticket,
+      soldAt: new Date(r.soldAt).toISOString(),
+      dishId,
+      qty,
+      needs: scaled(recipe, qty),
+    };
+  });
+
+  const existingTickets = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const pending = clean.filter((r) => !existingTickets.has(r.ticket));
+
+  const remaining = new Map();
+  for (const r of pending) {
+    for (const n of r.needs) {
+      if (!(n.qty > 0)) continue;
+      if (!remaining.has(n.itemId)) remaining.set(n.itemId, Math.round(onHand(store, n.itemId) * 1000) / 1000);
+      const available = remaining.get(n.itemId);
+      if (available < n.qty) {
+        const item = getItem(store, n.itemId);
+        throw new AppError("row_not_enough_stock", {
+          where: r.where,
+          item: item.name,
+          available,
+          unit: item.unit,
+        });
+      }
+      remaining.set(n.itemId, Math.round((available - n.qty) * 1000) / 1000);
+    }
+  }
+
+  store.data.sales ??= [];
+  const tickets = new Set();
+  let dishes = 0;
+  for (const r of pending) {
+    for (const n of r.needs) {
+      if (n.qty > 0) consume(store, n.itemId, n.qty, { at: r.soldAt, ref: `sale:${r.ticket}` });
+    }
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: r.ticket,
+      soldAt: r.soldAt,
+      dishId: r.dishId,
+      qty: r.qty,
+    });
+    tickets.add(r.ticket);
+    dishes += r.qty;
+  }
+
+  return { tickets: tickets.size, dishes };
+}
